/* ================= C3 · Supervision overview (regulator) ================= */
/* Every figure is computed from the data and opens the list behind it. */
const SEV = { 'Non-compliant': 3, 'Compliant with conditions': 2, Compliant: 1, 'Not assessed': 0 };
const liveSeries = () => S.series.filter(sr => S.cases.some(c => c.stage === 'Published' && progOf(c.prog).series === sr.id));
/* worst status across the organisation's latest result in each programme */
function orgOverall(org) { const st = liveSeries().map(sr => compStatus(latestResult(org, sr.id))).filter(s => s !== 'Not assessed'); return st.sort((a, b) => SEV[b] - SEV[a])[0] || 'Not assessed'; }
const verifiedOrgs = () => Object.values(S.orgs).filter(o => o.status === 'Verified');
const orgRow = (o, sub, chipHtml) => ({ org: o.id, sub: sub || esc(catLabel(o.type, o.tier)), chip: chipHtml || compChip(orgOverall(o.id)), go: orgGo(o.id) });
const prevResult = (org, sid) => S.cases.filter(c => c.org === org && c.stage === 'Published' && c.score != null && progOf(c.prog).series === sid).sort((a, b) => +progOf(b.prog).cycle - +progOf(a.prog).cycle)[1];
/* returns filed on time in the latest period of each active template */
function returnsOnTime() { const tps = S.returnTemplates.filter(t => t.status === 'Active'); const rows = []; tps.forEach(t => { const pers = [...new Set(S.filings.filter(f => f.tpl === t.id && f.due <= TODAY).map(f => f.pkey))].sort().reverse(); const pk = pers[0]; if (!pk) return; const fs = S.filings.filter(f => f.tpl === t.id && f.pkey === pk); rows.push({ t, period: fs[0].period, fs, on: fs.filter(f => isFiled(f) && !f.lateBy) }); }); return rows; }

/* ---------- Dashboard ---------- */
screen('dashboard', {
  t: 'Dashboard', layout: 'app', ws: 'regulator', crumbs: ['Dashboard', 'Supervision overview'],
  render() {
    Object.keys(DRILL).forEach(k => delete DRILL[k]);
    const p = persona(); const orgs = verifiedOrgs();
    const pend = { ver: Object.values(S.orgs).filter(o => o.status === 'Pending verification').length, cls: S.classReqs.filter(r => r.status === 'Pending').length, acc: S.accApps.filter(a => a.status === 'In review').length };
    const todo = [['seal-check', 'Organisations to verify', pend.ver, 'organisations:Pending verification'], ['git-diff', 'Classification changes', pend.cls, 'organisations:Change requested'], ['certificate', 'Accreditation applications', pend.acc, 'firms:In review'], ['stamp', 'Reports to review', S.cases.filter(c => c.stage === 'Report submitted').length, 'reviews:'], ['table', 'Returns to review', S.filings.filter(f => ['Submitted', 'Resubmitted'].includes(f.status)).length, 'returns:review'], ['flag', 'Fixes to close', fixesToClose().length, 'findings:close'], ['gavel', 'Enforcement decisions', S.enfCases.filter(c => ['Awaiting sign-off', 'Response received'].includes(c.status)).length, 'enforcement:'], ['eye', 'On the watchlist', watchlist().length, 'enforcement:watch']];
    const by = s => orgs.filter(o => orgOverall(o.id) === s);
    const nonc = by('Non-compliant'), comp = by('Compliant'), cond = by('Compliant with conditions'), na = by('Not assessed');
    const open = allFindings().filter(x => !['Closed', 'Noted'].includes(x.f.status) && x.f.cls !== 'OFI'); const over = open.filter(x => fdOverdue(x.f));
    const rot = returnsOnTime(); const allF = rot.flatMap(r => r.fs), onF = rot.flatMap(r => r.on);
    const fRow = x => ({ org: x.c.org, sub: `${esc(x.f.cls)}: ${esc(x.f.title)}`, chip: fdChip(x.f), go: `findings/view:${x.f.id}` });
    /* status across programmes */
    const parts = [{ l: 'Compliant', col: CH.ok }, { l: 'Compliant with conditions', col: CH.warn }, { l: 'Non-compliant', col: CH.bad }, { l: 'Not assessed', col: 'var(--neu-strong)', ink: 'var(--text)' }];
    const stRows = liveSeries().map(sr => { const cur = currentCycle(sr.id); const scope = cur ? scopeOrgs(cur).map(o => o.id) : []; const ids = [...new Set([...scope, ...S.cases.filter(c => progOf(c.prog).series === sr.id).map(c => c.org)])].filter(id => S.orgs[id] && S.orgs[id].status === 'Verified');
      return { l: sr.name, vals: parts.map(pt => { const l = ids.filter(id => compStatus(latestResult(id, sr.id)) === pt.l); return { n: l.length, drill: drillKey(`${sr.name}: ${pt.l}`, 'Latest published result', l.map(id => orgRow(S.orgs[id], (latestResult(id, sr.id) || {}).score != null ? `Score ${latestResult(id, sr.id).score} (${progOf(latestResult(id, sr.id).prog).cycle})` : 'Not assessed yet', compChip(pt.l)))) }; }), total: ids.length }; });
    /* categories: average latest ISR score */
    const types = [...new Set(orgs.map(o => o.type))].sort();
    const catRows = types.map(t => { const os = orgs.filter(o => o.type === t); const sc = os.map(o => liveSeries().map(sr => (latestResult(o.id, sr.id) || {}).score).find(v => v != null)).filter(v => v != null); return { t, n: os.length, a: avg(sc), nc: os.filter(o => orgOverall(o.id) === 'Non-compliant').length }; });
    /* biggest drops between the last two results in any programme */
    const drops = orgs.flatMap(o => liveSeries().map(sr => { const a = prevResult(o.id, sr.id), b = latestResult(o.id, sr.id); return a && b ? { o, sr, a: a.score, b: b.score, d: b.score - a.score } : null; }).filter(Boolean)).sort((x, y) => x.d - y.d).slice(0, 5).filter(x => x.d < 0);
    const wl = watchlist().slice(0, 5);
    const kp = (i, l, n, sub, drill, test) => `<button class="kpi" data-act="drill" data-arg="${drill}" data-test="${test}"><div class="row gap8">${tile(i, '', 'sm')}<span class="overline">${l}</span></div><div class="kpi-n tnum">${n}</div><div class="cap muted">${sub}</div></button>`;
    return `${myHero({ actions: heroBtn('Board pack', 'file-text', { act: 'scorecard', arg: 'board', test: 'board-pack' }) + heroBtn('New programme', 'plus', { go: 'programmes/new' }) + heroBtn('Issue a regulatory action', 'gavel', { go: 'enforcement/new' }) })}
      <div class="kpi-row">${kp('buildings', 'Organisations', orgs.length, `${comp.length} compliant · ${na.length} not assessed yet`, drillKey('Organisations under supervision', '', orgs.map(o => orgRow(o))), 'dk-orgs')}${kp('x-circle', 'Non-compliant', nonc.length, `${cond.length} more compliant with conditions`, drillKey('Non-compliant', 'In at least one programme, latest result', nonc.map(o => orgRow(o))), 'dk-nonc')}${kp('flag', 'Open findings', open.length, `${over.length} overdue · ${open.filter(x => x.f.cls === 'MaNC').length} major`, drillKey('Open findings', 'Not counting opportunities for improvement', open.map(fRow)), 'dk-find')}${kp('table', 'Returns on time', `${pct(onF.length, allF.length)}%`, `${onF.length} of ${allF.length} in the latest period`, drillKey('Filed on time in the latest period', rot.map(r => esc(r.t.code + ' ' + r.period)).join(' · '), onF.map(f => ({ org: f.org, sub: `${esc(tplOf(f.tpl).name)} ${esc(f.period)}`, chip: retChip(f), go: `returns/filing:${f.id}` }))), 'dk-ret')}</div>
      <p class="scope-line">All ${orgs.length} organisations under supervision · latest published results · click a figure to see the list</p>
      <div class="ch-grid2">${chCard('dash-status', `${nonc.length} organisations non-compliant in at least one programme`, 'Compliance status by programme, from each organisation\'s latest published result · click to see who', chStack(stRows, parts), miniTable(['Programme', ...parts.map(x => x.l)], stRows.map(r => [esc(r.l), ...r.vals.map(v => v.n)])))}
        ${chCard('dash-cat', 'Average score by category', 'Latest published score · click a category to open it', chBars(catRows.filter(r => r.a != null).map(r => ({ l: r.t, lh: `${esc(r.t)} <span class="cap muted">(${r.n})</span>`, v: r.a, col: CH.brand, vl: r.a, go: 'organisations/category:' + r.t })), { max: 100 }), miniTable(['Category', 'Organisations', 'Average score', 'Non-compliant'], catRows.map(r => [esc(r.t), r.n, r.a ?? '—', r.nc])), { foot: `<div class="row wrap gap6">${catRows.map(r => `<button class="pill" data-act="open" data-arg="organisations/category:${esc(r.t)}" data-test="cat-${r.t.replace(/ /g, '-')}">${esc(r.t)}${count(r.n)}</button>`).join('')}</div>` })}</div>
      <div class="ch-grid2"><div class="card p0 col"><div class="tbl-tools"><div class="grow"><div class="h4">Watchlist</div><div class="cap muted">${watchlist().length} flagged by your rules</div></div><a href="#enforcement" data-act="open" data-arg="enforcement:watch" class="small strong">Open enforcement</a></div><div class="list">${wl.map(w => { const o = S.orgs[w.org]; const oc = enfOpenFor(w.org); return `<button class="list-row" data-act="open" data-arg="${orgGo(w.org)}">${logo(o, 32)}<span class="grow" style="min-width:0"><span class="strong ell" style="display:block">${esc(o.name)}</span><span class="cap muted ell" style="display:block">${esc(w.reasons[0].text)}${w.reasons.length > 1 ? ` · +${w.reasons.length - 1} more` : ''}</span></span>${oc ? enfChip(oc.status) : chip('No case', 'neu')}</button>`; }).join('') || `<div style="padding:16px 20px">${empty('eye', 'Nobody flagged', '')}</div>`}</div></div>
        ${chCard('dash-drops', drops.length ? `${drops.length} biggest drops since the previous cycle` : 'No drops since the previous cycle', 'Score in the previous and latest cycle · click to open', chDots(drops.map(x => ({ l: x.o.name, a: x.a, b: x.b, go: orgGo(x.o.id) })), { min: 0, max: 100, ref: 70, key: ['Previous', 'Latest'] }), null)}</div>`;
  }
});
OPEN_HOOKS['enforcement'] = a => { if (a) S.ui.enfTab = a; };
OPEN_HOOKS['reviews'] = a => {};

/* ---------- Category view ---------- */
OPEN_HOOKS['organisations/category'] = a => { S.ui.catType = a; };
screen('organisations/category', {
  t: 'Category', layout: 'app', ws: 'regulator', crumbs: () => [['Organisations', 'organisations'], ((allTypes().find(x => x.name === S.ui.catType) || {}).plural || S.ui.catType || 'Category')],
  render() {
    Object.keys(DRILL).forEach(k => delete DRILL[k]);
    const t = S.ui.catType || 'Microfinance bank'; const sers = liveSeries(); const sid = ui('catSer', 'isr'); const sr = S.series.find(s => s.id === sid) || sers[0];
    const os = verifiedOrgs().filter(o => o.type === t);
    const res = os.map(o => ({ o, c: latestResult(o.id, sr.id), pv: prevResult(o.id, sr.id) })).sort((a, b) => ((b.c || {}).score ?? -1) - ((a.c || {}).score ?? -1));
    const done = res.filter(r => r.c); const b = +(S.compliance.bench[sr.id] ?? 70); const met = done.filter(r => r.c.score >= b);
    const allDone = verifiedOrgs().map(o => latestResult(o.id, sr.id)).filter(Boolean);
    const latestP = done.length ? progOf(done[0].c.prog) : currentCycle(sr.id); const secs = latestP.qset.sections.filter(s => s.on);
    const secRows = secs.map(s => ({ l: s.name, a: avg(allDone.map(c => caseScore(c, s.id)).filter(v => v != null)), b: avg(done.map(r => caseScore(r.c, s.id)).filter(v => v != null)) }));
    const plural = (allTypes().find(x => x.name === t) || {}).plural || t + 's';
    return `<div class="rh"><div class="rh-main"><div class="overline">Category</div><div class="rh-title"><h1 class="h1">${esc(plural)}</h1>${chip(os.length + ' organisations', 'neu')}</div><div class="rh-meta">Ranked by their latest ${esc(sr.name)} result</div></div><div class="rh-act">${sers.length > 1 ? sel('cat-ser', sers.map(x => [x.id, x.name]), sr.id, { attrs: 'data-change="catSer" style="width:auto;height:36px" aria-label="Programme"' }) : ''}${btn('Export scorecard', { v: 'secondary', i: 'export', act: 'scorecard', arg: 'cat|' + t + '|' + sr.id, test: 'cat-export' })}</div></div>
      <div class="ktiles">${kTile('Organisations', os.length, { drill: drillKey(plural, '', os.map(o => orgRow(o))) })}${kTile('Assessed', done.length, { sub: `${os.length - done.length} not assessed yet`, drill: drillKey('Assessed', esc(sr.name), done.map(r => orgRow(r.o, `Score ${r.c.score}`))) })}${kTile('Average score', avg(done.map(r => r.c.score)) ?? '—', { sub: `All categories: ${avg(allDone.map(c => c.score)) ?? '—'}` })}${kTile(`Met the benchmark (${b})`, `${met.length}<small> · ${pct(met.length, done.length)}%</small>`, { drill: drillKey('Met the benchmark', esc(sr.name), met.map(r => orgRow(r.o, `Score ${r.c.score}`))), test: 'ck-met' })}</div>
      <div class="ch-grid2">${chCard('cat-sec', `Section scores: ${esc(plural.toLowerCase())} against all organisations`, `Average section score in the latest ${esc(sr.name)} results`, chDots(secRows.map(r => ({ l: r.l, a: r.a, b: r.b })), { min: 0, max: 100, ref: b, key: ['All organisations', plural] }), miniTable(['Section', 'All organisations', plural], secRows.map(r => [esc(r.l), r.a ?? '—', r.b ?? '—'])))}
        ${chCard('cat-status', 'Compliance status', `${esc(sr.name)}, latest result`, chStack([{ l: plural, vals: ['Compliant', 'Compliant with conditions', 'Non-compliant', 'Not assessed'].map(s => { const l = res.filter(r => compStatus(r.c) === s); return { n: l.length, drill: drillKey(s, esc(plural), l.map(r => orgRow(r.o, r.c ? `Score ${r.c.score}` : 'Not assessed yet', compChip(s)))) }; }), total: res.length }], [{ l: 'Compliant', col: CH.ok }, { l: 'Compliant with conditions', col: CH.warn }, { l: 'Non-compliant', col: CH.bad }, { l: 'Not assessed', col: 'var(--neu-strong)', ink: 'var(--text)' }]), null)}</div>
      <div class="card p0"><div class="tbl-tools"><div class="grow"><div class="h4">Ranking</div><div class="cap muted">Click an organisation to see its compliance history</div></div></div><div class="tbl-wrap"><table class="tbl dense"><thead><tr><th class="num">#</th><th>Organisation</th><th class="num">Score</th><th class="num">Change</th><th>Status</th>${secs.map(s => `<th class="num" title="${esc(s.name)}">${esc(s.name.replace(/^\d+\.\s*/, '').split(' ')[0])}</th>`).join('')}<th class="num">Open findings</th></tr></thead><tbody>${res.map((r, i) => { const d = r.c && r.pv ? r.c.score - r.pv.score : null; const of = r.c ? (r.c.findings || []).filter(NC_OPEN).length : 0; return `<tr class="click" data-act="open" data-arg="organisations/profile:${r.o.id}|compliance" data-test="rank-${r.o.id}"><td class="num tnum muted">${r.c ? i + 1 : '—'}</td><td>${orgCell(r.o, r.o.tier || '')}</td><td class="num tnum strong" style="color:${r.c && r.c.score < b ? 'var(--bad-fg)' : 'inherit'}">${r.c ? r.c.score : '—'}</td><td class="num tnum">${d == null ? '<span class="muted">—</span>' : `<span style="color:${d >= 0 ? 'var(--ok-fg)' : 'var(--bad-fg)'}">${d > 0 ? '+' : ''}${d}</span>`}</td><td>${compChip(compStatus(r.c))}</td>${secs.map(s => { const v = r.c ? caseScore(r.c, s.id) : null; return `<td class="num tnum ${v != null && v < b ? 'neg' : ''}">${v ?? '—'}</td>`; }).join('')}<td class="num tnum">${of || '—'}</td></tr>`; }).join('')}</tbody></table></div></div>`;
  }
});
ACT.chg_catSer = v => { S.ui.catSer = v; render(); };

/* ---------- Organisation → Compliance tab ---------- */
function orgComplianceReg(o) {
  Object.keys(DRILL).forEach(k => delete DRILL[k]);
  const sers = liveSeries().filter(sr => S.cases.some(c => c.org === o.id && progOf(c.prog).series === sr.id));
  const cyc = sr => S.cases.filter(c => c.org === o.id && progOf(c.prog).series === sr.id).sort((a, b) => +progOf(a.prog).cycle - +progOf(b.prog).cycle);
  const years = [...new Set(sers.flatMap(sr => cyc(sr).map(c => +progOf(c.prog).cycle)))].sort();
  const cols = [CH.brand, CH.ai, CH.ok, CH.warn];
  const line = years.length > 1 ? chLine({ w: 560, h: 210, x: { min: years[0] - 0.2, max: years[years.length - 1] + 0.2, ticks: years.map(y => [y, String(y)]) }, y: { min: 0, max: 100, ticks: [0, 50, 100] }, series: sers.map((sr, i) => ({ name: sr.name, col: cols[i % cols.length], dots: true, pts: cyc(sr).filter(c => c.stage === 'Published' && c.score != null).map(c => [+progOf(c.prog).cycle, c.score]) })).filter(s => s.pts.length), refY: [{ v: 70, label: 'Benchmark 70' }], label: 'Score history' }) : '<p class="small muted">History appears after a second cycle.</p>';
  const isr = latestResult(o.id, 'isr'); const fs = allFindings().filter(x => x.c.org === o.id && x.f.cls !== 'OFI');
  const openF = fs.filter(x => !['Closed', 'Noted'].includes(x.f.status));
  const fl = (S.filings || []).filter(f => f.org === o.id && (isFiled(f) || f.due < TODAY)); const onT = fl.filter(f => isFiled(f) && !f.lateBy);
  const enf = S.enfCases.filter(c => c.org === o.id);
  return `<div class="card p0"><div class="tbl-tools"><div class="grow"><div class="h4">Status by programme</div><div class="cap muted">Overall: ${compChip(orgOverall(o.id))}</div></div>${btn('Export scorecard', { v: 'secondary', size: 'sm', i: 'export', act: 'scorecard', arg: 'org|' + o.id, test: 'org-export' })}</div><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Programme</th><th>Latest cycle</th><th class="num">Score</th><th class="num">Change</th><th>Status</th><th>Firm</th><th class="num">Open findings</th></tr></thead><tbody>${sers.map(sr => { const c = latestResult(o.id, sr.id); const pv = prevResult(o.id, sr.id); const live = cyc(sr).find(x => x.stage !== 'Published'); return `<tr class="click" data-act="open" data-arg="reviews/report:${c ? c.id : ''}" data-test="oc-${sr.id}"><td class="small strong">${esc(sr.name)}${live ? `<div class="cap muted">${esc(progOf(live.prog).cycle)}: ${esc(live.stage)}</div>` : ''}</td><td class="small">${c ? esc(progOf(c.prog).cycle) : '—'}</td><td class="num tnum strong">${c ? c.score : '—'}</td><td class="num tnum">${c && pv ? `${c.score - pv.score > 0 ? '+' : ''}${c.score - pv.score}` : '—'}</td><td>${compChip(compStatus(c))}</td><td class="small">${c && S.firms[c.firm] ? esc(S.firms[c.firm].name) : '—'}</td><td class="num tnum">${c ? (c.findings || []).filter(NC_OPEN).length || '—' : '—'}</td></tr>`; }).join('')}</tbody></table></div></div>
    <div class="ch-grid2">${chCard('oc-hist', 'Score history', 'Each programme, every published cycle', line, null)}${chCard('oc-sec', isr ? `Section scores in ${esc(progOf(isr.prog).name)}` : 'Section scores', 'Latest published result', isr ? chBars(progOf(isr.prog).qset.sections.filter(s => s.on).map(s => { const v = caseScore(isr, s.id); return { l: s.name, v: v || 0, vl: v ?? '—', col: v != null && v < 70 ? CH.bad : CH.brand }; }), { max: 100 }) : '<p class="small muted">Not assessed yet.</p>', null)}</div>
    <div class="ch-grid2"><div class="card p0 col"><div class="tbl-tools"><div class="grow"><div class="h4">Findings</div><div class="cap muted">${openF.length} open · ${openF.filter(x => fdOverdue(x.f)).length} overdue · ${fs.length - openF.length} closed</div></div></div><div class="list">${openF.slice(0, 6).map(x => `<button class="list-row" data-act="open" data-arg="findings/view:${x.f.id}">${clsChip(x.f.cls)}<span class="grow ell small">${esc(x.f.title)}</span>${fdChip(x.f)}</button>`).join('') || `<div style="padding:12px 20px" class="small muted">No open findings.</div>`}</div></div>
      <div class="card col gap12"><div class="h4">Returns and enforcement</div>${kv([['Returns filed on time', fl.length ? `${onT.length} of ${fl.length} (${pct(onT.length, fl.length)}%)` : 'None due yet'], ['Late or not filed', String(fl.filter(f => retStatus(f) === 'Late' || f.lateBy).length)], ['Enforcement cases', enf.length ? enf.map(c => `<a href="#" data-act="open" data-arg="enforcement/case:${c.id}">${esc(c.ref)}</a> ${esc(atOf(c.type).name.toLowerCase())}, ${esc(c.status.toLowerCase())}`).join('<br>') : 'None']])}</div></div>`;
}

/* ---------- Data returns → Insights ---------- */
function retInsights() {
  Object.keys(DRILL).forEach(k => delete DRILL[k]);
  const tps = S.returnTemplates.filter(t => t.status === 'Active'); const due = S.filings.filter(f => tplOf(f.tpl).status === 'Active' && f.due <= TODAY);
  const fRow = f => ({ org: f.org, sub: `${esc(tplOf(f.tpl).name)} ${esc(f.period)}${f.lateBy ? ` · ${f.lateBy} days late` : ''}`, chip: retChip(f), go: `returns/filing:${f.id}` });
  const groups = []; tps.forEach(t => [...new Set(due.filter(f => f.tpl === t.id).map(f => f.pkey))].sort().forEach(pk => groups.push({ t, pk, fs: due.filter(f => f.tpl === t.id && f.pkey === pk) })));
  const parts = [{ l: 'On time', col: CH.ok }, { l: 'Late', col: CH.warn }, { l: 'Not filed', col: CH.bad }];
  const rows = groups.map(g => { const on = g.fs.filter(f => isFiled(f) && !f.lateBy), late = g.fs.filter(f => isFiled(f) && f.lateBy), nf = g.fs.filter(f => !isFiled(f)); return { l: `${g.t.code} ${g.fs[0].period}`, vals: [on, late, nf].map((l, i) => ({ n: l.length, drill: drillKey(`${g.t.code} ${g.fs[0].period}: ${parts[i].l.toLowerCase()}`, esc(g.t.name), l.map(fRow)) })), total: `${pct(on.length, g.fs.length)}%` }; });
  const filed = due.filter(isFiled); const queried = filed.filter(f => (f.queries || []).length); const late = due.filter(f => f.lateBy || retStatus(f) === 'Late');
  const byOrg = {}; late.forEach(f => { byOrg[f.org] = (byOrg[f.org] || []).concat(f); }); const rep = Object.keys(byOrg).sort((a, b) => byOrg[b].length - byOrg[a].length);
  return `<div class="ktiles">${kTile('Filings due so far', due.length, { drill: drillKey('Filings due so far', '', due.map(fRow)) })}${kTile('Filed on time', `${pct(filed.filter(f => !f.lateBy).length, due.length)}%`, { sub: `${filed.filter(f => !f.lateBy).length} of ${due.length}` })}${kTile('Late or not filed', late.length, { sub: 'Past the due date', drill: drillKey('Late or not filed', '', late.map(fRow)), test: 'ri-late' })}${kTile('Queried', `${pct(queried.length, filed.length)}%`, { sub: `${queried.length} of ${filed.length} filed returns`, drill: drillKey('Queried', '', queried.map(fRow)) })}</div>
    <div class="ch-grid2">${chCard('ri-period', 'Filing on time by return and period', 'Click a segment to see who', chStack(rows, parts), miniTable(['Return and period', ...parts.map(x => x.l)], rows.map(r => [esc(r.l), ...r.vals.map(v => v.n)])))}
      ${chCard('ri-late', rep.length ? `${rep.length} organisations late at least once` : 'Nobody late', 'Late or not filed, by organisation · click to open', chBars(rep.slice(0, 10).map(o => ({ l: S.orgs[o].name, v: byOrg[o].length, col: CH.warn, drill: drillKey(S.orgs[o].name, 'Late or not filed', byOrg[o].map(fRow)) }))), null)}</div>`;
}

/* ---------- Findings → Insights ---------- */
function fdInsights() {
  Object.keys(DRILL).forEach(k => delete DRILL[k]);
  const all = allFindings().filter(x => x.f.cls !== 'OFI'); const open = all.filter(x => !['Closed', 'Noted'].includes(x.f.status)); const over = open.filter(x => fdOverdue(x.f));
  const closed = all.filter(x => x.f.status === 'Closed' && x.f.closedDate); const pubISO = x => { const d = new Date(x.c.published); return isNaN(d) ? null : d.toISOString().slice(0, 10); };
  const ttc = k => avg(closed.filter(x => x.f.cls === k && pubISO(x)).map(x => daysBetween(pubISO(x), x.f.closedDate)).filter(v => v >= 0));
  const row = x => ({ org: x.c.org, sub: `${esc(x.f.cls)}: ${esc(x.f.title)}`, chip: fdChip(x.f), go: `findings/view:${x.f.id}` });
  const cls = ['MaNC', 'MiNC', 'OBS']; const colOf = { MaNC: CH.bad, MiNC: CH.warn, OBS: CH.brand };
  const types = [...new Set(open.map(x => S.orgs[x.c.org].type))].sort();
  const stack = chStack(types.map(t => ({ l: t, vals: cls.map(k => { const l = open.filter(x => x.f.cls === k && S.orgs[x.c.org].type === t); return { n: l.length, drill: drillKey(`${t}: ${k}`, 'Open findings', l.map(row)) }; }), total: open.filter(x => S.orgs[x.c.org].type === t).length })), cls.map(k => ({ l: `${k} · ${fcOf(k).name}`, col: colOf[k] })));
  /* overdue at each month end, last 8 months */
  const ends = []; for (let m = 7; m >= 0; m--) { const d = new Date('2026-10-01T12:00:00'); d.setMonth(d.getMonth() - m); d.setDate(0); ends.push(d.toISOString().slice(0, 10)); } ends.push(TODAY);
  const overAt = d => all.filter(x => effDue(x.f) && effDue(x.f) < d && (!x.f.closedDate || x.f.closedDate > d) && (x.f.status !== 'Closed' || x.f.closedDate) && (pubISO(x) || '') <= d).length;
  const pts = ends.map((d, i) => [i, overAt(d)]);
  const line = chLine({ w: 560, h: 210, x: { min: 0, max: ends.length - 1, ticks: ends.map((d, i) => [i, i === ends.length - 1 ? 'Today' : new Date(d + 'T12:00:00').toLocaleDateString('en-GB', { month: 'short' })]) }, y: { min: 0, max: Math.max(5, ...pts.map(p => p[1])), ticks: [0, Math.max(5, ...pts.map(p => p[1]))] }, series: [{ name: 'Overdue fixes', col: CH.bad, pts, end: String(pts[pts.length - 1][1]) }], label: 'Overdue fixes at each month end' });
  return `<div class="ktiles">${kTile('Open findings', open.length, { sub: 'Across all programmes', drill: drillKey('Open findings', '', open.map(row)), test: 'fi-open' })}${kTile('Overdue', over.length, { sub: `${over.filter(x => x.f.cls === 'MaNC').length} major`, drill: drillKey('Overdue fixes', '', over.map(row)), test: 'fi-over' })}${kTile('Closed', closed.length, { sub: 'All time', drill: drillKey('Closed', '', closed.map(row)) })}${kTile('Days to close a major', ttc('MaNC') ?? '—', { sub: `Minor ${ttc('MiNC') ?? '—'} · observation ${ttc('OBS') ?? '—'}` })}</div>
    <div class="ch-grid2">${chCard('fi-cat', 'Open findings by category and class', 'Click a segment to see which', stack, miniTable(['Category', ...cls], types.map(t => [esc(t), ...cls.map(k => open.filter(x => x.f.cls === k && S.orgs[x.c.org].type === t).length)])))}${chCard('fi-trend', `${over.length} fixes overdue today`, 'Overdue fixes at the end of each month', line, miniTable(['Month end', 'Overdue'], ends.map((d, i) => [fmtD(d), pts[i][1]])))}</div>`;
}
